(68, 17, 'ar', 'قسم العلوم الاجتماعية والتربية البدنية', 'العلوم الاجتماعية والتربية البدنية', 'قسم العلوم الاجتماعية والتربية البدنية ضمن كلية الخدمات والرقمنة يعد متخصصين عبر التعليم الحديث والتدريب المخبري والتعاون المباشر مع قطاعات الصناعة.', '[{\"key\":\"prepared_specialists\",\"title\":\"\\u0627\\u0644\\u062a\\u062e\\u0635\\u0635\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u064a\\u062a\\u0645 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0647\\u0627\",\"items\":[]},{\"key\":\"subjects\",\"title\":\"\\u0627\\u0644\\u0645\\u0642\\u0631\\u0631\\u0627\\u062a \\u0627\\u0644\\u062f\\u0631\\u0627\\u0633\\u064a\\u0629\",\"items\":[]},{\"key\":\"research\",\"title\":\"\\u0627\\u0644\\u0623\\u0639\\u0645\\u0627\\u0644 \\u0627\\u0644\\u0628\\u062d\\u062b\\u064a\\u0629\",\"items\":[\"\\u064a\\u0637\\u0648\\u0631 \\u0627\\u0644\\u0642\\u0633\\u0645 \\u0627\\u0644\\u0628\\u062d\\u0648\\u062b \\u0627\\u0644\\u062a\\u0637\\u0628\\u064a\\u0642\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0645\\u0634\\u0627\\u0631\\u064a\\u0639 \\u0627\\u0644\\u0627\\u0628\\u062a\\u0643\\u0627\\u0631\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0639\\u0645\\u0644 \\u0627\\u0644\\u0639\\u0644\\u0645\\u064a \\u0644\\u0644\\u0637\\u0644\\u0627\\u0628.\"]},{\"key\":\"cooperation\",\"title\":\"\\u0627\\u0644\\u062a\\u0639\\u0627\\u0648\\u0646\",\"items\":[\"\\u062a\\u062a\\u0643\\u0627\\u0645\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062a\\u0639\\u0644\\u064a\\u0645\\u064a\\u0629 \\u0645\\u0639 \\u0627\\u0644\\u0645\\u0624\\u0633\\u0633\\u0627\\u062a \\u0627\\u0644\\u0635\\u0646\\u0627\\u0639\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0645\\u0646\\u0638\\u0645\\u0627\\u062a \\u0627\\u0644\\u0639\\u0644\\u0645\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062c\\u0627\\u0645\\u0639\\u0627\\u062a \\u0627\\u0644\\u0634\\u0631\\u064a\\u0643\\u0629.\"]},{\"key\":\"publications\",\"title\":\"\\u0627\\u0644\\u0645\\u0646\\u0634\\u0648\\u0631\\u0627\\u062a\",\"items\":[]},{\"key\":\"plans\",\"title\":\"\\u0627