INSERT INTO `faculty_translations` (`id`, `faculty_id`, `locale`, `name`, `short_name`, `description`, `content_sections`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES
(1, 1, 'en', 'Faculty of Technology', 'Technology', 'The Faculty of Technology trains specialists for chemical technology, food production, oil and gas processing, metrology and agricultural product processing.', '[]', 'Faculty of Technology', 'The Faculty of Technology trains specialists for chemical technology, food production, oil and gas processing, metrology and agricultural product processing.', '2026-07-26 00:16:43', '2026-07-26 00:16:56'),
(2, 1, 'uz', 'Texnologiya fakulteti', 'Texnologiya', 'Texnologiya fakulteti kimyoviy texnologiya, oziq-ovqat ishlab chiqarish, neft va gazni qayta ishlash, metrologiya hamda qishloq xo‘jaligi mahsulotlarini qayta ishlash bo‘yicha mutaxassislar tayyorlaydi.', '[]', 'Texnologiya fakulteti', 'Texnologiya fakulteti kimyoviy texnologiya, oziq-ovqat ishlab chiqarish, neft va gazni qayta ishlash, metrologiya hamda qishloq xo‘jaligi mahsulotlarini qayta ishlash bo‘yicha mutaxassislar tayyorlaydi.', '2026-07-26 00:16:43', '2026-07-26 00:16:56'),
(3, 1, 'ru', 'Технологический факультет', 'Технология', 'Технологический факультет готовит специалистов по химической технологии, пищевому производству, переработке нефти и газа, метрологии и переработке сельхозпродукции.', '[]', 'Технологический факультет', 'Технологический факультет готовит специалистов по химической технологии, пищевому производству, переработке нефти и газа, метрологии и переработке сельхозпродукции.', '2026-07-26 00:16:43', '2026-07-26 00:16:56'),
(4, 1, 'ar', 'كلية التكنولوجيا', 'التكنولوجيا', 'تعد كلية التكنولوجيا متخصصين في التكنولوجيا الكيميائية وإنتاج الأغذية ومعالجة النفط والغاز والمترولوجيا ومعالجة المنتجات الزراعية.', '[]', 'كلية التكنولوجيا', 'تعد كلية التكنولوجيا متخصصين في التكنولوجيا الكيميائية وإنتاج الأغذية ومعالجة النفط والغاز والمترولوجيا ومعالجة المنتجات الزراعية.', '2026-07-26 00:16:43', '2026-07-26 00:16:56'),
(5, 2, 'en', 'Faculty of Service and Digitalization', 'Service & Digitalization', 'The faculty brings together economics, management, tourism, ICT, automation, exact sciences, social sciences and language education for a digital university environment.', '[]', 'Faculty of Service and Digitalization', 'The faculty brings together economics, management, tourism, ICT, automation, exact sciences, social sciences and language education for a digital university environment.', '2026-07-26 00:16:43', '2026-07-26 00:16:56'),
(6, 2, 'uz', 'Servis va raqamlashtirish fakulteti', 'Servis va raqamlashtirish', 'Fakultet raqamli universitet muhitida iqtisodiyot, menejment, turizm, AKT, avtomatlashtirish, aniq fanlar, ijtimoiy fanlar va tillarni birlashtiradi.', '[]', 'Servis va raqamlashtirish fakulteti', 'Fakultet raqamli universitet muhitida iqtisodiyot, menejment, turizm, AKT, avtomatlashtirish, aniq fanlar, ijtimoiy fanlar va tillarni birlashtiradi.', '2026-07-26 00:16:43', '2026-07-26 00:16:56'),
(7, 2, 'ru', 'Факультет сервиса и цифровизации', 'Сервис и цифровизация', 'Факультет объединяет экономику, менеджмент, туризм, ИКТ, автоматизацию, точные науки, социальные науки и языковое образование в цифровой университетской среде.', '[]', 'Факультет сервиса и цифровизации', 'Факультет объединяет экономику, менеджмент, туризм, ИКТ, автоматизацию, точные науки, социальные науки и языковое образование в цифровой университетской среде.', '2026-07-26 00:16:43', '2026-07-26 00:16:56'),
(8, 2, 'ar', 'كلية الخدمات والرقمنة', 'الخدمات والرقمنة', 'تجمع الكلية بين الاقتصاد والإدارة والسياحة وتقنيات المعلومات والأتمتة والعلوم الدقيقة والاجتماعية وتعليم اللغات ضمن بيئة جامعية رقمية.', '[]', 'كلية الخدمات والرقمنة', 'تجمع الكلية بين الاقتصاد والإدارة والسياحة وتقنيات المعلومات والأتمتة والعلوم الدقيقة والاجتماعية وتعليم اللغات ضمن بيئة جامعية رقمية.', '2026-07-26 00:16:43', '2026-07-26 00:16:56'),
(9, 3, 'en', 'Faculty of Natural Resources Management', 'Natural Resources', 'The faculty prepares engineers for water management, land cadastre, ecology, hydrogeology, vehicle engineering, geodesy and environmental protection.', '[]', 'Faculty of Natural Resources Management', 'The faculty prepares engineers for water management, land cadastre, ecology, hydrogeology, vehicle engineering, geodesy and environmental protection.', '2026-07-26 00:16:43', '2026-07-26 00:16:56'),
(10, 3, 'uz', 'Tabiiy resurslarni boshqarish fakulteti', 'Tabiiy resurslar', 'Fakultet suv xo‘jaligi, yer kadastri, ekologiya, gidrogeologiya, transport muhandisligi, geodeziya va atrof-muhit muhofazasi bo‘yicha muhandislar tayyorlaydi.', '[]', 'Tabiiy resurslarni boshqarish fakulteti', 'Fakultet suv xo‘jaligi, yer kadastri, ekologiya, gidrogeologiya, transport muhandisligi, geodeziya va atrof-muhit muhofazasi bo‘yicha muhandislar tayyorlaydi.', '2026-07-26 00:16:43', '2026-07-26 00:16:56'),
(11, 3, 'ru', 'Факультет управления природными ресурсами', 'Природные ресурсы', 'Факультет готовит инженеров по водному хозяйству, земельному кадастру, экологии, гидрогеологии, транспортной инженерии, геодезии и охране окружающей среды.', '[]', 'Факультет управления природными ресурсами', 'Факультет готовит инженеров по водному хозяйству, земельному кадастру, экологии, гидрогеологии, транспортной инженерии, геодезии и охране окружающей среды.', '2026-07-26 00:16:43', '2026-07-26 00:16:56'),
(12, 3, 'ar', 'كلية إدارة الموارد الطبيعية', 'الموارد الطبيعية', 'تعد الكلية مهندسين في إدارة المياه والسجل العقاري والبيئة والهيدروجيولوجيا وهندسة المركبات والجيوديسيا وحماية البيئة.', '[]', 'كلية إدارة الموارد الطبيعية', 'تعد الكلية مهندسين في إدارة المياه والسجل العقاري والبيئة والهيدروجيولوجيا وهندسة المركبات والجيوديسيا وحماية البيئة.', '2026-07-26 00:16:43', '2026-07-26 00:16:56');
